for guide in GUIDES:
    guide['published_at'] = date(2026, 11, 11)
    guide['updated_at'] = guide['published_at']
    guide['path'] = '/guides/' + guide['slug'] + '/'
    guide['seo_title'] = guide['title'] + ' — TenderSearch'
    words = guide['intro'].split()
    for index, item in enumerate(guide['sections'], 1):
        item['id'] = 'section-' + str(index)
        words += ' '.join([item['title'], *item['paragraphs'], *item['bullets']]).split()
    guide['reading_minutes'] = max(2, ceil(len(words) / 180))

GUIDE_BY_SLUG = {guide['slug']: guide for guide in GUIDES}
